# RegOptimizer - Windows Registry Optimizer
# Requires -RunAsAdministrator

Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing

# ============================================================
#  SAFETY: Automatic BCD backup before any bcdedit changes
#  This lets the user roll back boot settings with the
#  "RESTORE BOOT SETTINGS" task if a tweak causes boot issues.
# ============================================================
try {
    $bcdBackupDir = Join-Path $env:ProgramData "AudenOptimizer\BCD_Backup"
    if (-not (Test-Path $bcdBackupDir)) { New-Item -Path $bcdBackupDir -ItemType Directory -Force | Out-Null }
    $bcdBackupFile = Join-Path $bcdBackupDir ("bcd_backup_{0}.bcd" -f (Get-Date -Format 'yyyyMMdd_HHmmss'))
    bcdedit /export "$bcdBackupFile" 2>&1 | Out-Null
} catch {}

# ---
#  Registry Tasks Definition
# ---
$Tasks = @(
    @{
        ID       = 0
        Name     = "RESTORE BOOT SETTINGS (SAFETY)"
        Desc     = "Restore BCD boot configuration from the automatic backup made when this tool was launched. Use this if a BCD tweak causes boot problems."
        Category = "SAFETY"
        Action   = {
            $backupDir = Join-Path $env:ProgramData "AudenOptimizer\BCD_Backup"
            $latest = Get-ChildItem -Path $backupDir -Filter "*.bcd" -ErrorAction SilentlyContinue |
                      Sort-Object LastWriteTime -Descending | Select-Object -First 1
            if ($latest) {
                $r = bcdedit /import $latest.FullName 2>&1
                "Restored BCD from $($latest.Name). $r Restart the PC for changes to take effect."
            } else {
                "No BCD backup file found in $backupDir"
            }
        }
