    # ==============================================
    #  BCDEDIT LOW LATENCY BOOT (LowLatencyBoost.bat)
    # ==============================================
    @{
        ID       = 56
        Name     = "BCDEDIT LOW LATENCY BOOT (SAFE SUBSET)"
        Desc     = "disabledynamictick, useplatformtick, tscsyncpolicy Enhanced, bootmenupolicy standard, timeout=5. The unsafe legacy options (nx optout, increaseuserva, firstmegabytepolicy, avoidlowmemory, nolowmem, linearaddress57, hypervisor/VBS toggles) have been removed - they were causing 'computer won't boot' on many systems and are covered by other, safer tweaks if needed."
        Category = "BCDEDIT"
        Action   = {
            $cmds = @(
                "bcdedit /set disabledynamictick yes",
                "bcdedit /set useplatformtick yes",
                "bcdedit /set tscsyncpolicy Enhanced",
                "bcdedit /set bootmenupolicy standard",
                "bcdedit /timeout 5"
            )
            $results = @()
            foreach ($cmd in $cmds) {
                try {
                    $out = Invoke-Expression "$cmd 2>&1"
                    $results += "$cmd -> OK"
                } catch {
                    $results += "$cmd -> FAILED: $_"
                }
            }
            ($results -join "`r`n") + "`r`nA BCD backup was taken at launch. Use 'RESTORE BOOT SETTINGS' if needed."
        }
    },

