            if (-not (Test-Path $ak)) { New-Item -Path $ak -Force | Out-Null }
            Set-ItemProperty -Path $ak -Name "Flags"              -Value "186"  -Type String -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $ak -Name "MaximumSpeed"       -Value "40"   -Type String -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $ak -Name "TimeToMaximumSpeed" -Value "3000" -Type String -Force -ErrorAction SilentlyContinue

            $dk = "HKCU:\Control Panel\Desktop"
            if (-not (Test-Path $dk)) { New-Item -Path $dk -Force | Out-Null }
            Set-ItemProperty -Path $dk -Name "MenuShowDelay"        -Value "0" -Type String -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $dk -Name "UseDoubleClickTimer"  -Value 0   -Type DWord  -Force -ErrorAction SilentlyContinue

            $ek = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced"
            if (-not (Test-Path $ek)) { New-Item -Path $ek -Force | Out-Null }
            Set-ItemProperty -Path $ek -Name "DisallowShaking"  -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $ek -Name "TaskbarBadges"    -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $ek -Name "Start_TrackDocs"  -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue

            $ep = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Explorer"
            if (-not (Test-Path $ep)) { New-Item -Path $ep -Force | Out-Null }
            Set-ItemProperty -Path $ep -Name "NoUseStoreOpenWith"      -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $ep -Name "DisableNotificationCenter" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue

            "Mouse + UI extended tweaks applied"
        }
    }

)
# ---
#  System Info
# ---
function Get-SysInfo {
    $os  = (Get-CimInstance Win32_OperatingSystem).Caption
    $cpu = (Get-CimInstance Win32_Processor).Name
    $ram = [math]::Round((Get-CimInstance Win32_ComputerSystem).TotalPhysicalMemory / 1GB, 1)
    $nic = (Get-CimInstance Win32_NetworkAdapter -Filter "NetEnabled='True'" | Select-Object -First 1).ProductName
    return @{ OS = $os; CPU = $cpu; RAM = "$ram GB"; NIC = $nic }
}

