function New-FlatButton {
    param($Text, $X, $Y, $WW, $H, $BG, $FG, $Font)
    $btn = New-Object System.Windows.Forms.Button
    $btn.Text      = $Text
    $btn.Location  = New-Object System.Drawing.Point($X, $Y)
    $btn.Size      = New-Object System.Drawing.Size($WW, $H)
    $btn.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
    $btn.FlatAppearance.BorderSize  = 1
    $btn.FlatAppearance.BorderColor = $C.Border
    $btn.BackColor  = $BG
    $btn.ForeColor  = $FG
    $btn.Font       = $Font
    $btn.Cursor     = [System.Windows.Forms.Cursors]::Hand
    return $btn
}

function New-Lbl {
    param($Text, $X, $Y, $WW, $H, $FG, $Font, $Align = "MiddleLeft")
    $lbl = New-Object System.Windows.Forms.Label
    $lbl.Text      = $Text
    $lbl.Location  = New-Object System.Drawing.Point($X, $Y)
    $lbl.Size      = New-Object System.Drawing.Size($WW, $H)
    $lbl.ForeColor = $FG
    $lbl.Font      = $Font
    $lbl.BackColor = [System.Drawing.Color]::Transparent
    $lbl.TextAlign = [System.Drawing.ContentAlignment]::$Align
    return $lbl
}

function New-Sep {
    param($X, $Y, $WW)
    $sep = New-Object System.Windows.Forms.Panel
    $sep.Location  = New-Object System.Drawing.Point($X, $Y)
    $sep.Size      = New-Object System.Drawing.Size($WW, 1)
    $sep.BackColor = $C.Border
    return $sep
}

