$imgBytes  = [System.Convert]::FromBase64String($imgB64)
$imgStream = New-Object System.IO.MemoryStream(,$imgBytes)
$bgImage   = [System.Drawing.Image]::FromStream($imgStream)

$form.Add_Paint({
    param($s, $e)
    [int]$clientW = $form.ClientSize.Width
    [int]$clientH = $form.ClientSize.Height
    if ($clientW -le 0 -or $clientH -le 0) { return }
    $ia = New-Object System.Drawing.Imaging.ImageAttributes
    $cm = New-Object System.Drawing.Imaging.ColorMatrix
    $cm.Matrix33 = 0.52
    $ia.SetColorMatrix($cm)
    # Draw bg prominently below header (y=64)
    [int]$headerH = 64
    $destRect = New-Object System.Drawing.Rectangle(0, $headerH, $clientW, ($clientH - $headerH))
    # Source: proportional crop to match destination
    [int]$srcY = [int]([math]::Max(0, ($bgImage.Height * $headerH / $clientH) - 80))
    [int]$srcH = [int]$bgImage.Height - $srcY
    if ($srcH -le 0) { return }
    [int]$imgW = [int]$bgImage.Width
    $e.Graphics.DrawImage($bgImage, $destRect, 0, $srcY, $imgW, $srcH, [System.Drawing.GraphicsUnit]::Pixel, $ia)
})


