# ---
#  Log Helper
# ---
function Write-Log {
    param($Msg, $Color = $null)
    $time = Get-Date -Format "HH:mm:ss"
    $txtLog.SelectionStart  = $txtLog.TextLength
    $txtLog.SelectionLength = 0
    $txtLog.SelectionColor  = $C.TextDim
    $txtLog.AppendText("$time  ")
    $txtLog.SelectionColor  = if ($Color) { $Color } else { $C.Text }
    $txtLog.AppendText("$Msg`n")
    $txtLog.ScrollToCaret()
    $form.Refresh()
}

# ---
#  Init Log
# ---
$form.Add_Shown({
    # Re-center in case ISE or DPI caused offset
    $screen = [System.Windows.Forms.Screen]::PrimaryScreen.WorkingArea
    $form.Left = [int](($screen.Width  - $form.Width)  / 2) + $screen.Left
    $form.Top  = [int](($screen.Height - $form.Height) / 2) + $screen.Top

    Write-Log "Initialized" $C.OK
    Write-Log "OS   $($sysInfo.OS)" $C.Text
    Write-Log "CPU  $($sysInfo.CPU)" $C.Text
    Write-Log "RAM  $($sysInfo.RAM)" $C.Text
    Write-Log ""
    Write-Log "Tasks loaded: $($Tasks.Count) registry operations" $C.AccentLt
    Write-Log ""
    Write-Log "Press [ Run RegOptimizer ] to start." $C.Warn
})

# ---
#  RUN Button
# ---
$btnRun.Add_Click({
    $isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
    if (-not $isAdmin) {
        Write-Log "ERROR: Must run as Administrator!" $C.Err
        return
    }

    $btnRun.Enabled     = $false
    $btnRun.Text        = "Running..."
    $lblReady.Text      = "[*] RUNNING"
    $lblReady.ForeColor = $C.Warn

    $total = $Tasks.Count
    $done  = 0
    $barW  = [int]$FW - 32

    foreach ($task in $Tasks) {
        $lblCurTask.Text = "[$($task.ID) / $total]  $($task.Name)"
        $curFill.Width   = 0
        $form.Refresh()

        Write-Log ""
        Write-Log "[$($task.ID)]  $($task.Name)" $C.Accent
        Write-Log "     $($task.Desc)" $C.TextMid

        for ($p = 0; $p -le 100; $p += 20) {
            $curFill.Width = [int]($barW * $p / 100)
            Start-Sleep -Milliseconds 55
            $form.Refresh()
        }

        try {
            $result = & $task.Action
            Write-Log "     OK  $result" $C.OK
        } catch {
            Write-Log "     FAIL  $_" $C.Err
        }

        $done++
        $pct = [int](100 * $done / $total)
        $progressFill.Width = [int](($barW) * $done / $total)
        $lblPct.Text        = "$pct%"
        $curFill.Width      = $barW
        $form.Refresh()
        Start-Sleep -Milliseconds 180
    }

    $lblCurTask.Text = "Running gpupdate /force..."
    $form.Refresh()
    Write-Log ""
    Write-Log "Running gpupdate /force..." $C.Warn
    try {
        $gpResult = gpupdate /force 2>&1
        Write-Log "     OK  Group Policy updated" $C.OK
    } catch {
        Write-Log "     FAIL  $_" $C.Err
    }

    $lblCurTask.Text     = "All $total tasks completed."
    $lblReady.Text       = "[*] DONE"
    $lblReady.ForeColor  = $C.OK
    Write-Log ""
    Write-Log "All $total tasks completed successfully." $C.OK
    Write-Log "A restart is recommended for changes to take effect." $C.Warn
    $btnRun.Text    = "Completed"
    $btnRun.Enabled = $true
})

# ---
#  CLEAR / EXIT
# ---
$btnClear.Add_Click({
    $txtLog.Clear()
    $progressFill.Width = 0
    $curFill.Width      = 0
    $lblPct.Text        = "0%"
    $lblCurTask.Text    = "Waiting to start..."
    $lblReady.Text      = "[*] READY"
    $lblReady.ForeColor = $C.OK
    $btnRun.Text        = "Run RegOptimizer"
    Write-Log "Cleared." $C.TextDim
})

$btnExit.Add_Click({ $form.Close() })

[System.Windows.Forms.Application]::Run($form)
